use serde::{Serialize, Deserialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Node {
    pub next: Box<Next>,

    pub value: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NodeClass {
    pub next: Box<Next>,

    pub value: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Next {
    NodeClass(NodeClass),

    PurpleString(String),
}
